import{_ as t,o as a,c as i,a3 as e}from"./chunks/framework.CVt6dz2a.js";const c=JSON.parse('{"title":"EP.19 给帧率发工资：16.6ms 怎么花","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.19-performance-budget.md","filePath":"comics/EP.19-performance-budget.md","lastUpdated":1793881879000}'),r={name:"comics/EP.19-performance-budget.md"};function n(o,s,l,d,h,p){return a(),i("div",null,[...s[0]||(s[0]=[e(`<h1 id="ep-19-给帧率发工资-16-6ms-怎么花" tabindex="-1">EP.19 给帧率发工资：16.6ms 怎么花 <a class="header-anchor" href="#ep-19-给帧率发工资-16-6ms-怎么花" aria-label="Permalink to &quot;EP.19 给帧率发工资：16.6ms 怎么花&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/19-engineering-performance/basics">19.1 基础入门：性能预算与采集</a> 延伸阅读：<a href="./../guide/19-engineering-performance/advanced">进阶篇</a> · <a href="./../guide/19-engineering-performance/practice">实战篇</a> 动手演示：<a href="./../public/demos/performance/dispose-lab.html">dispose-lab 内存泄漏实验室</a> · <a href="./../public/demos/performance/quality-tiers.html">quality-tiers 画质分级适配</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><table tabindex="0"><thead><tr><th>格</th><th>场景</th></tr></thead><tbody><tr><td>① 困境</td><td>像素酱的页面在开发机上 60 帧，却被投诉：用户红米老机只有 20 帧、帧时间 47ms——同一套代码，高端机满帧、低端机崩盘，没有预算表，优化全凭感觉。</td></tr><tr><td>② 揭秘</td><td>码叔点破：每帧 16.6ms 是总预算，JS 脚本领 4ms、CPU 提交领 6ms、GPU 渲染领 6ms——渲染、脚本、合成都从这笔钱里领，谁超支谁拖帧。</td></tr><tr><td>③ 实证</td><td>画质分三档后自动选档：低端机切低档（dpr 1、关阴影、关 Bloom、实例 6000→1200），帧时间 47ms→17ms，FPS 21→55；预算表贴在工位，每版按指标验收。</td></tr><tr><td>④ 结案</td><td>码叔总结：优化不是感觉，是指标；附坑点清单——别只看平均 FPS、dispose 别漏共享资源、自动降档要加锁定。</td></tr></tbody></table><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="_1-16-6ms-帧时间的-工资单" tabindex="-1">① 16.6ms：帧时间的&quot;工资单&quot; <a class="header-anchor" href="#_1-16-6ms-帧时间的-工资单" aria-label="Permalink to &quot;① 16.6ms：帧时间的&quot;工资单&quot;&quot;">​</a></h3><p>60fps 意味着每帧只有 <strong>16.6ms</strong>（1000/60），JS 脚本、CPU 提交、GPU 渲染、浏览器合成全从这一份预算里领钱，任何一项超支整帧迟到。性能预算就是把这份工资单提前写死：</p><table tabindex="0"><thead><tr><th>指标</th><th>高端桌面</th><th>中端手机</th><th>低端机</th></tr></thead><tbody><tr><td>帧时间</td><td>≤16.6ms</td><td>≤16.6ms</td><td>≤33.3ms</td></tr><tr><td>draw calls</td><td>≤3000</td><td>≤500</td><td>≤150</td></tr><tr><td>纹理显存</td><td>≤2GB</td><td>≤512MB</td><td>≤256MB</td></tr></tbody></table><p>预算按<strong>目标设备中最弱的一档</strong>定，并预留约 30% 余量给系统与 GC。</p><h3 id="_2-采集三板斧" tabindex="-1">② 采集三板斧 <a class="header-anchor" href="#_2-采集三板斧" aria-label="Permalink to &quot;② 采集三板斧&quot;">​</a></h3><ul><li><strong>Stats.js</strong>：FPS / MS / MB 三页面板，开发期常驻；MS 页比 FPS 更直观；</li><li><strong>Performance API</strong>：<code>performance.now()</code> 掐帧时间、<code>performance.memory.usedJSHeapSize</code> 读 JS 堆（仅 Chrome 系）；</li><li><strong>DevTools Performance 面板</strong>：红色长帧定位掉帧现场，火焰图看钱被谁领走。</li></ul><p>关键认知：<strong>峰值帧时间比平均帧率更能反映卡顿</strong>——平均 60fps 也可能偶尔一帧 80ms，人眼一定能察觉。</p><h3 id="_3-实证-画质三档分级" tabindex="-1">③ 实证：画质三档分级 <a class="header-anchor" href="#_3-实证-画质三档分级" aria-label="Permalink to &quot;③ 实证：画质三档分级&quot;">​</a></h3><p>同一楼群场景三档切换，按&quot;整帧成本&quot;从高到低动刀：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> TIERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  high: { dpr: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   shadow: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2048</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, bloom: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,  count: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  mid:  { dpr: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, shadow: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1024</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, bloom: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, count: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  low:  { dpr: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   shadow: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,    bloom: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, count: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1200</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>启动时设备特征（cores / memory / dpr）粗判 + 试跑 2 秒精调；运行中滚动统计帧时间，<strong>连续 3 个窗口超标才降档</strong>，降后锁定 10 秒防横跳。实测低端机帧时间 47ms→17ms，FPS 回到 55。</p><h3 id="_4-配套纪律-内存与验收" tabindex="-1">④ 配套纪律：内存与验收 <a class="header-anchor" href="#_4-配套纪律-内存与验收" aria-label="Permalink to &quot;④ 配套纪律：内存与验收&quot;">​</a></h3><ul><li><strong>dispose 全家桶</strong>：geometry / material / texture / renderTarget 逐一释放，共享资源引用计数，SPA 路由切换时按序收尸（停循环 → 摘监听 → 释放场景 → renderer.dispose）；</li><li><strong>性能报告模板</strong>：机型 / 档位 / FPS / 帧时间均值与峰值 / calls / 三角形 / 内存，结论只有&quot;达标 / 可接受 / 不达标&quot;，没有&quot;还行&quot;。</li></ul><h2 id="坑点清单-faq" tabindex="-1">坑点清单（FAQ） <a class="header-anchor" href="#坑点清单-faq" aria-label="Permalink to &quot;坑点清单（FAQ）&quot;">​</a></h2><ul><li><strong>Q：平均 60fps 为什么还卡？</strong> FPS 是平均值，会掩盖尖峰长帧。盯帧时间的峰值与方差（Stats MS 页、自写 HUD），常见元凶是 GC、纹理首次上传与着色器即时编译。</li><li><strong>Q：dispose 了内存还涨？</strong> 查三处：共享材质/纹理被漏算或重复释放、RenderTarget 与 PMREM 没 dispose、JS 侧引用没断（数组/闭包/回调里还挂着）。</li><li><strong>Q：自动降档被投诉&quot;画面突然变糊&quot;？</strong> 连续超标才降、降档弹提示、允许用户手动锁档；降档后加锁定期，避免两档间反复横跳比掉帧更晃眼。</li><li><strong>Q：performance.memory 非 Chrome 没有怎么办？</strong> <code>if (performance.memory)</code> 兜底显示 N/A；显存自己按&quot;宽×高×4×1.33&quot;估算；跨浏览器验收以帧时间为硬指标。</li></ul><h2 id="自测-quiz" tabindex="-1">自测（Quiz） <a class="header-anchor" href="#自测-quiz" aria-label="Permalink to &quot;自测（Quiz）&quot;">​</a></h2><ol><li>为什么性能预算要按&quot;目标设备中最弱的一档&quot;来定，而不是按团队开发机的水平？</li><li>统计自动降档时，为什么用&quot;连续 3 个窗口帧时间超标&quot;而不是&quot;一帧超过 20ms 就降&quot;？</li><li>SPA 路由切走 3D 页面时，只把 <code>&lt;canvas&gt;</code> 从 DOM 移除会有什么后果？至少补两步收尸操作。</li></ol><details><summary>答案</summary><ol><li>预算的意义是<strong>保证体验下限</strong>。开发机普遍是高端设备，按它定预算，低端机必然超支掉帧——而低端机用户往往正是大众产品的基本盘。按最弱档定红线、预留 30% 余量，高端机自然轻松达标。</li><li>单次掉帧可能只是 GC、纹理上传等瞬时抖动，立刻降档会让画质无谓波动、在两档间反复横跳。连续多个统计窗口超标才说明是<strong>持续性负载过高</strong>，此时降档才是真对症；配合降后锁定期，画质才稳定。</li><li>canvas 移除了，但渲染循环还在跑、GPU 资源全活着，来回切换十几次低端机直接白屏。收尸顺序：<code>renderer.setAnimationLoop(null)</code> 停循环 → 摘事件监听 → <code>scene.traverse</code> 全树 dispose → <code>composer?.dispose()</code> → <code>renderer.dispose()</code> + <code>forceContextLoss()</code>。</li></ol></details>`,23)])])}const m=t(r,[["render",n]]);export{c as __pageData,m as default};
